                            category: 'enterprise',
                            status: 'active',
                            region: 'west',
                            lat: 37.7749,
                            lng: -122.4194
                        },
                        {
                            key: '2',
                            name: 'Beta LLC',
                            address: '456 Oak Ave, New York, NY',
                            category: 'retail',
                            status: 'active',
                            region: 'east',
                            lat: 40.7128,
                            lng: -74.0060
                        }
                    ],
                    columns: [
                        { title: 'Name', dataIndex: 'name', key: 'name' },
                        { title: 'Address', dataIndex: 'address', key: 'address' },
                        { title: 'Category', dataIndex: 'category', key: 'category' },
                        { title: 'Status', dataIndex: 'status', key: 'status' },
                        { title: 'Region', dataIndex: 'region', key: 'region' },
                        { title: 'Actions', key: 'action' }
                    ]
                };
            },
            async mounted() {
                await this.initMap();
                this.displayMarkers(this.customers);

                // Set up filter listeners
                this.setupFilterListeners();
            },
            methods: {
                async initMap() {
                    const { Map } = await google.maps.importLibrary("maps");
                    const { AdvancedMarkerElement } = await google.maps.importLibrary("marker");

                    this.map = new Map(document.getElementById("map"), {
                        center: { lat: 39.8283, lng: -98.5795 }, // Center of US
                        zoom: 4,
                        mapId: "DEMO_MAP_ID",
                        mapTypeControl: true,
                        zoomControl: true,
                        streetViewControl: true,
                        fullscreenControl: true
                    });

                    // Store libraries for later use
                    this.AdvancedMarkerElement = AdvancedMarkerElement;
                },

                displayMarkers(customers) {
                    // Clear existing markers
                    this.markers.forEach(marker => marker.map = null);
                    this.markers = [];

                    // Create new markers
                    customers.forEach(customer => {
                        if (customer.lat && customer.lng) {
                            const marker = new this.AdvancedMarkerElement({
                                map: this.map,
                                position: { lat: customer.lat, lng: customer.lng },
                                title: customer.name
                            });

                            // Add click listener
                            marker.addListener("click", () => {
                                this.showCustomerInfo(customer);
                            });

                            this.markers.push({
                                marker,
                                customer
                            });
                        }
                    });
                },

                showCustomerInfo(customer) {
                    // Create info window
                    const infoWindow = new google.maps.InfoWindow({
                        content: `
                            <div style="padding: 10px">
                                <h3>${customer.name}</h3>
                                <p><strong>Address:</strong> ${customer.address}</p>
                                <p><strong>Category:</strong> ${customer.category}</p>
                                <p><strong>Status:</strong> ${customer.status}</p>
                                <p><strong>Region:</strong> ${customer.region}</p>
                            </div>
                        `
                    });

                    // Open info window at marker position
                    infoWindow.open({
                        anchor: this.markers.find(m => m.customer.key === customer.key)?.marker,
                        map: this.map
                    });
                },

                showOnMap(customer) {
                    // Center map on customer
                    this.map.setCenter({ lat: customer.lat, lng: customer.lng });
                    this.map.setZoom(12);

                    // Show info window
                    this.showCustomerInfo(customer);
                },

                setupFilterListeners() {
                    // Set up event listeners for filter changes
                    // In a real implementation, you would bind to Vue events
                    // This is a simplified version
                    const filterMarkers = () => {
                        // Get filter values (simplified)
                        const regionFilter = document.querySelector('[placeholder="Filter by Region"]')?.value;
                        const categoryFilter = document.querySelector('[placeholder="Filter by Category"]')?.value;
                        const statusFilter = document.querySelector('[placeholder="Filter by Status"]')?.value;

                        // Filter customers
                        const filteredCustomers = this.customers.filter(customer => {
                            return (!regionFilter || customer.region === regionFilter) &&
                                   (!categoryFilter || customer.category === categoryFilter) &&
                                   (!statusFilter || customer.status === statusFilter);
                        });

                        // Update markers
                        this.displayMarkers(filteredCustomers);
                    };

                    // Add event listeners to filter controls
                    document.querySelectorAll('.ant-select-selector').forEach(select => {
                        select.addEventListener('change', filterMarkers);
                    });
                },

                // Method to geocode addresses (if you only have addresses, not lat/lng)
                async geocodeAddress(address) {
                    const { Geocoder } = await google.maps.importLibrary("geocoding");
                    const geocoder = new Geocoder();

                    return new Promise((resolve, reject) => {
                        geocoder.geocode({ address: address }, (results, status) => {
                            if (status === "OK" && results[0]) {
                                const location = results[0].geometry.location;
                                resolve({
                                    lat: location.lat(),
                                    lng: location.lng()
                                });
                            } else {
                                reject(new Error("Geocode failed: " + status));
                            }
                        });
                    });
                }
            }
        };

        createApp(App)
            .use(antd)
            .mount('#app');
    </script>
